"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[9427],{28453:(n,h,t)=>{t.d(h,{R:()=>a,x:()=>o});var c=t(96540);const i={},g=c.createContext(i);function a(n){const h=c.useContext(g);return c.useMemo(function(){return"function"==typeof n?n(h):{...h,...n}},[h,n])}function o(n){let h;return h=n.disableParentContext?"function"==typeof n.components?n.components(i):n.components||i:a(n.components),c.createElement(g.Provider,{value:h},n.children)}},62983:n=>{n.exports=JSON.parse('{"permalink":"/blog/cai-chet","source":"@site/blog/20261014-cai-chet.md","title":"C\xe1i ch\u1ebft","description":"N\u0103m 2023, m\xecnh c\xf3 \u0111i b\u01a1i bi\u1ec3n 1 l\u1ea7n, m\u1ed9t s\u1ef1 ki\u1ec7n \u0111\u01b0\u1ee3c t\u1ed5 ch\u1ee9c \u1edf Kh\xe1nh Ho\xe0 tr\u01b0\u1edbc VnExpress Marathon 1 ng\xe0y.","date":"2026-10-14T00:00:00.000Z","tags":[{"inline":false,"label":"Life","permalink":"/blog/tags/life","description":"Everyday life, home, and living"}],"readingTime":3.86,"hasTruncateMarker":true,"authors":[{"name":"Khanh Ha","title":"cat-server/ex-da","page":{"permalink":"/blog/authors/khanh-ha"},"imageURL":"https://github.com/khanhhabmt/blog-media/releases/download/media-assets/bach.jpg","key":"khanh-ha"}],"frontMatter":{"slug":"cai-chet","title":"C\xe1i ch\u1ebft","authors":["khanh-ha"],"tags":["life"],"date":"2026-10-14T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"Kh\xf4ng c\xf3 g\xec \u0111\u1ec3 m\u1eb7c","permalink":"/blog/khong-co-gi-de-mac"}}')},71163:(n,h,t)=>{t.r(h),t.d(h,{assets:()=>e,contentTitle:()=>o,default:()=>s,frontMatter:()=>a,metadata:()=>c,toc:()=>m});var c=t(62983),i=t(74848),g=t(28453);const a={slug:"cai-chet",title:"C\xe1i ch\u1ebft",authors:["khanh-ha"],tags:["life"],date:new Date("2026-10-14T00:00:00.000Z")},o=void 0,e={authorsImageUrls:[void 0]},m=[];function r(n){const h={br:"br",hr:"hr",p:"p",...(0,g.R)(),...n.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(h.p,{children:["N\u0103m 2023, m\xecnh c\xf3 \u0111i b\u01a1i bi\u1ec3n 1 l\u1ea7n, m\u1ed9t s\u1ef1 ki\u1ec7n \u0111\u01b0\u1ee3c t\u1ed5 ch\u1ee9c \u1edf Kh\xe1nh Ho\xe0 tr\u01b0\u1edbc VnExpress Marathon 1 ng\xe0y.",(0,i.jsx)(h.br,{}),"\n","C\xf9ng th\u1eddi gian nh\xe0 c\u1ee7a m\xecnh \u0111ang x\xe2y. L\xfac \u0111\xf3 c\xf3 suy ngh\u0129, l\u1ee1 m\xecnh kh\xf4ng may t\xe8o th\xec sao. \xd4ng b\xe0 gi\xe0 m\u1ea5t con bu\u1ed3n \u0111au \u0111\xe3 \u0111\xe0nh, l\u1ea1i th\xeam c\xe1i nh\xe0 n\xf3 \u0111ang x\xe2y d\u1edf...",(0,i.jsx)(h.br,{}),"\n","Ngh\u0129 v\u1eady n\xean m\xecnh d\u1eabn m\u1eb9 ra ng\xe2n h\xe0ng, nh\u1edd m\u1eb9 \u0111\u1ee9ng t\xean \u0111\u1ed3ng ch\u1ee7 t\xe0i kho\u1ea3n trong m\u1ed9t kho\u1ea3ng th\u1eddi gian, \u0111\u1ec3 l\u1ee1 c\xf3 g\xec c\xf2n l\u1ea5y ti\u1ec1n thanh to\xe1n cho b\xean th\u1ea7u theo ti\u1ebfn \u0111\u1ed9 cho \u0111\u1ee1 r\xe1ch vi\u1ec7c."]}),"\n",(0,i.jsx)(h.p,{children:"Kh\xf4ng nh\u1edb l\xfac \u0111\xf3 c\u1ee5 n\xf3i g\xec, nh\u01b0ng m\u1eb9 m\xecnh \u0111\u01b0\u1ee3c c\xe1i l\xe0 kh\xf4ng overthinking, kh\xf4ng drama, n\xf3i chuy\u1ec7n \u0111\u01a1n gi\u1ea3n, h\u1ee9a c\u1ed1 g\u1eafng to\xe0n m\u1ea1ng tr\u1edf v\u1ec1, c\u1ee5 c\u0169ng \u0111\xe0nh ok."}),"\n",(0,i.jsx)(h.hr,{}),"\n",(0,i.jsx)(h.p,{children:"M\u1ea5y n\u0103m tr\u01b0\u1edbc, b\u1ed1 h\u1ecfi, sao m kh\xf4ng \u0111\u1ebb l\u1ea5y \u0111\u1ee9a con? L\u01b0u \xfd, c\u1ee5 \u0111\xe3 kh\xf4ng h\u1ecfi c\xe2u, sao m kh\xf4ng l\u1ea5y ch\u1ed3ng, t\u1eeb r\u1ea5t r\u1ea5t l\xe2u r\u1ed3i, c\u1ee5 \u0111\xe3 b\u1ecf \u0111i vi\u1ec7c h\u1ecfi c\xe2u \u0111\u1ea5y. M\xecnh, l\xfac \u0111\xf3 c\xf2n \u0111ang h\u0103ng h\xe1i l\xe0m cu li t\u01b0 b\u1ea3n v\xe0 kh\xf4ng ngh\u0129 ra \u0111\u1eddi m\xecnh c\u1ea7n m\u1ee5c \u0111\xedch g\xec h\u01a1n l\xe0 \u0111i l\xe0m t\xedch tr\u1eef t\xe0i s\u1ea3n v\xe0 enjoy bao nhi\xeau c\xe1i hay ho, h\u1ecfi b\u1ed1, v\xec sao \u1ea1? B\u1ed1 b\u1ea3o, \u0111\u1ec3 c\xf3 \u0111\u1ed9ng l\u1ef1c m\xe0 s\u1ed1ng ch\u1ee9 sao."}),"\n",(0,i.jsx)(h.p,{children:"\u0110\u1ea7u n\u0103m nay, \u0111i xem show ra, n\xf3i chuy\u1ec7n v\u1edbi Hi\u1ebfu, \u0111\u1ea1i kh\xe1i, t c\u0169ng kh\xf4ng bi\u1ebft t l\xe0m g\xec cho h\u1ebft \u0111\u1eddi n\u1eefa, c\xf3 \u0111\xf4i khi t th\u1ea5y b\u1ed1 t n\xf3i \u0111\xfang, kh\xf4ng c\xf3 con c\xe1i th\xec \u0111\u1ed9ng l\u1ef1c \u0111\xe2u m\xe0 s\u1ed1ng. N\xf3 c\u0169ng \u0111\u1ed3ng \xfd, cu\u1ed9c \u0111\u1eddi n\xf3 b\xe2y gi\u1edd ch\u1ec9 xoay quanh th\u1eb1ng con th\xf4i. T\u1eeb ng\xe0y c\xf3 con, l\xfac n\xe0o qua \u0111\u01b0\u1eddng n\xf3 c\u0169ng \u0111i \u1edf v\u1ea1ch k\u1ebb cho ng\u01b0\u1eddi \u0111i b\u1ed9. \u0110\u1ed9ng l\u1ef1c s\u1ed1ng tuy\u1ec7t \u0111\u1ed1i m\u1ea1nh m\u1ebd."}),"\n",(0,i.jsx)(h.hr,{}),"\n",(0,i.jsx)(h.p,{children:"M\u1edbi \u0111\xe2y, g\u1eb7p l\u1ea1i th\u1eb1ng b\u1ea1n c\xf9ng \u0111i thi m\u1ed9t cu\u1ed9c thi qu\u1ed1c t\u1ebf nh\u1ea3m nh\xed th\u1eddi sinh vi\xean, n\xf3 ly h\xf4n v\xe0 c\xf3 m\u1ed9t c\xf4 con g\xe1i. N\xf3 b\u1ea3o, t v\u1eabn mu\u1ed1n c\xf3 th\xeam con, \u0111\xf3 l\xe0 s\u1ef1 ti\u1ebfp n\u1ed1i, m hi\u1ec3u kh\xf4ng? M\xecnh ko hi\u1ec3u, n\xf3 l\u1ea5y v\xed d\u1ee5, b\xe2y gi\u1edd t \u0111i ngh\u0129a trang th\u0103m m\u1ed9 c\xe1c c\u1ee5 trong h\u1ecd, m s\u1ebd th\u1ea5y c\xe2y ph\u1ea3 h\u1ec7 n\xf3 hi\u1ec7n l\xean m\u1ea1nh m\u1ebd theo m\u1eadt \u0111\u1ed9 kh\xf3i h\u01b0\u01a1ng. T\u1edbi nh\xe1nh n\xe0o m\xe0 kh\xf4ng c\xf3 con c\xe1i, \u0111\u1eb7c bi\u1ec7t l\xe0 con trai ti\u1ebfp n\u1ed1i, nh\xecn c\xe1i m\u1ed9 l\xe0 hi\u1ec3u ngay. M\xecnh th\u1eafc m\u1eafc, v\xec sao \u0111i\u1ec1u \u0111\xf3 l\u1ea1i quan tr\u1ecdng khi m\xecnh \u0111\xe3 t\u1ea1ch r\u1ed3i h\u1ea3 m? T ngh\u0129 l\xe0 d\xf9 t c\xf3 con hay ko th\xec t v\u1eabn s\u1ebd ho\u1ea3 t\xe1ng sau khi t\xe8o v\xe0 tro r\u1eafc \u0111i \u0111\xe2u \u0111\xf3 n\u1ebfu t\u1ed1t, c\xf2n kh\xf4ng th\xec b\xf3n c\xe2y hay l\xe0m xi m\u0103ng g\xec c\u0169ng \u0111\u01b0\u1ee3c, t c\u0169ng ko care cho l\u1eafm."}),"\n",(0,i.jsx)(h.p,{children:'R\u1ed3i n\xf3 c\u0169ng l\u1ea1i n\xf3i m\u1ed9t c\xe2u y chang \xf4ng b\u1ed1 m\xecnh: "mu\u1ed1n c\xf3 th\u1eb1ng cu \u0111\u1ec3 sau n\xe0y t\xe8o c\xf3 \u0111\u1ee9a ch\u1ed1ng g\u1eady".'}),"\n",(0,i.jsx)(h.p,{children:"Xong kh\xf4ng nh\u1edb sao n\xf3i \u0111\u1ebfn chuy\u1ec7n h\u1ecd h\xe0ng, n\xf3 b\u1ea3o, m c\xf3 bi\u1ebft h\u1ecd h\xe0ng g\u1eb7p nhau nhi\u1ec1u nh\u1ea5t \u1edf \u0111\xe2u kh\xf4ng? \u1edf \u0111\xe1m ma. Khi c\xf3 \u0111\xe1m ma trong h\u1ecd, th\xec m\xecnh s\u1ebd g\u1eb7p h\u1ecd h\xe0ng, ho\u1eb7c kh\xf4ng \u0111\u1ebfn th\xec m\xecnh c\u0169ng s\u1ebd li\xean l\u1ea1c v\u1edbi h\u1ecd h\xe0ng \u0111\u1ec3 nh\u1edd g\u1eedi ph\xfang \u0111i\u1ebfu."}),"\n",(0,i.jsx)(h.p,{children:"Kh\xf4ng hi\u1ec3u sao m\xe0 th\u1eb1ng b\u1ea1n m\xecnh n\xf3 l\u1ea1i \xe1m \u1ea3nh v\u1edbi \u0111\xe1m ma v\xe0 ngh\u0129a trang \u0111\u1ebfn nh\u01b0 th\u1ebf. Nh\u01b0ng th\xf4i th\xec m\u1ed7i ng\u01b0\u1eddi c\xf3 logic c\u1ee7a m\xecnh. May m\xe0 v\u1eabn n\xf3i chuy\u1ec7n ch\u1ee9 kh\xf4ng \u0111\u1ea5m nhau l\xe0 ok r\u1ed3i."}),"\n",(0,i.jsx)(h.hr,{}),"\n",(0,i.jsx)(h.p,{children:"Crush ng\xe0y x\u01b0a c\u1ee7a m\xecnh, c\xf3 vi\u1ebft m\u1ed9t t\xe2m s\u1ef1, r\u1eb1ng nh\u1eefng d\u1ecbp Gi\xe1ng Sinh, \u1ed5ng \u0111i b\u1ed9 trong tuy\u1ebft, \u0111i qua nh\u1eefng ng\xf4i nh\xe0 \u0111ang s\xe1ng \u0111\xe8n v\xe0ng qu\xe2y qu\u1ea7n c\xf9ng nhau. \u1ed4ng nh\xecn nh\u01b0ng kh\xf4ng bao gi\u1edd ngh\u0129 \u0111\xe2y l\xe0 cu\u1ed9c s\u1ed1ng d\xe0nh cho m\xecnh."}),"\n",(0,i.jsx)(h.p,{children:"\u1ed4ng c\u0169ng c\xf3 t\u1eebng vi\u1ebft v\u1ec1 c\xe1i ch\u1ebft. \u0110\u1ea1i kh\xe1i \u1ed5ng raise m\u1ed9t c\xe2u h\u1ecfi: khi b\u1ecb g\u1ea5u r\u01b0\u1ee3t trong r\u1eebng th\xec ph\u1ea3i l\xe0m sao n\u1ebfu crush m\xecnh l\xe0 ng\u01b0\u1eddi ch\u1ea1y ch\u1eadm nh\u1ea5t, m\xecnh ch\u1ea1y ch\u1eadm nh\xec v\xe0 c\xe1c thanh ni\xean kh\xe1c ch\u1ea1y nhanh h\u01a1n? Solution c\u1ee7a \u1ed5ng l\xe0: \u0110\xe1 qu\xe8 gi\xf2 m\u1ed9t anh thanh ni\xean \u0111\u1ec3 th\xed m\u1ea1ng cho c\u1ea3 \u0111\u1ed9i, ho\u1eb7c h\xf4n crush m\u1ed9t l\u1ea7n duy nh\u1ea5t trong \u0111\u1eddi r\u1ed3i \u0111\u1ee9ng l\u1ea1i l\xe0m v\u1eadt hi sinh, flash back cu\u1ed9c \u0111\u1eddi xong kh\xf4ng qu\xean t\u01b0\u1edfng t\u01b0\u1ee3ng th\xeam c\xf4 crush khi tr\u1edf th\xe0nh 1 b\xe0 l\xe3o l\u1ee5 kh\u1ee5, ng\u1ed3i b\xean \u0111\u1ed1ng l\u1eeda, k\u1ec3 cho con ch\xe1u v\u1ec1 s\u1ef1 hi sinh c\u1ee7a m\xecnh b\u1eb1ng \u0111\xf4i m\u1eaft l\u1ea5p l\xe1nh."}),"\n",(0,i.jsx)(h.p,{children:"H\u1eebm, t\xf4i c\u1ee9 t\u01b0\u1edfng ch\u1eafc \u1ed5ng solo c\u1ea3 \u0111\u1eddi, nh\u01b0ng kh\xf4ng, khi b\u1eb1ng tu\u1ed5i t\xf4i b\xe2y gi\u1edd, \u1ed5ng \u0111\xe3 l\u1ea5y v\u1ee3."})]})}function s(n={}){const{wrapper:h}={...(0,g.R)(),...n.components};return h?(0,i.jsx)(h,{...n,children:(0,i.jsx)(r,{...n})}):r(n)}}}]);